head.script:
scwin.screenId = "jlddst35400";

///////// 1. 변수 및 선언 영역 /////////

scwin.dtree = undefined;

scwin.contn = "${fn:replace(sysInfo.contn, \"\"\", \"\\\"\")}";

scwin.keyword = "${fn:replace(param.keyword, \"\"\", \"\\\"\")}";


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jlddst35400: 진입 키 explanationsystem 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst35400.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_keyword_onkeypress
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_keyword_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_keyword_onkeypress — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.keyEvent(event)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst35400.ipt_keyword_onkeypress' }); }
};

/**
 * @event
 * @name scwin.btn_fnSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearch_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fnSearch(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst35400.btn_fnSearch_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_sysInfoList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_sysInfoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_sysInfoList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_sysInfoList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_ViewSysInfo('${sysInfo.helpClssId}'); return false; (EL 미해석) */
        return false; return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_sysInfoList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ViewSysInfo_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ViewSysInfo_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewSysInfo_xhr", unresolved: "action:self_submit:tx_fn_ViewSysInfo_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.viewSysInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_sysInfoClssId
 * @returns
 * @hidden N
*/
scwin.viewSysInfo = async function (ipt_sysInfoClssId) {
    /* sdd-asis-lifecycle:begin fn_ViewSysInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_ViewSysInfoXhrReq").set("sysInfoClssId", ipt_sysInfoClssId);
    const result = await scwin.tx_fn_ViewSysInfo_xhr();
    (console.error('[sdd] 이 화면 문서에 #sysInfoContext 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#sysInfoContext")).html(result);
    scwin.dtree.open(ipt_sysInfoClssId);
    scwin.dtree.selected(ipt_sysInfoClssId);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#searchForm").submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.replaceKeyword
 * @author Inswave
 * @date 2026. 09. 29
 * @param srcStr keyword
 * @returns
 * @hidden N
*/
scwin.replaceKeyword = function (srcStr, keyword) {
    /* sdd-asis-lifecycle:begin fn_ReplaceKeyword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    document.write(srcStr.replace(new RegExp(keyword, "g"), "<span class='search'>" + keyword + "</span>"));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = async function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < scwin.dtree.aNodes.length; i++) {
        if (!scwin.dtree.aNodes[i]._hc) {
            await scwin.viewSysInfo(scwin.dtree.aNodes[i].id);
            break;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param evt
 * @returns
 * @hidden N
*/
scwin.keyEvent = function (evt) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const evCode = (false) ? evt.which : $c.util.getKeyCode(event);
    if (evCode == 13) {
        scwin.fnSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnPageGo
 * @author Inswave
 * @date 2026. 09. 29
 * @param page
 * @returns
 * @hidden N
*/
scwin.fnPageGo = function (page) {
    /* sdd-asis-lifecycle:begin fnPageGo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_pageIndex', page) : console.warn('[sdd] hiddenStore 부재: ipt_pageIndex'));
    scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.pageNav
 * @author Inswave
 * @date 2026. 09. 29
 * @param funcName pageNum pageSize total
 * @returns
 * @hidden N
*/
scwin.pageNav = function (funcName, pageNum, pageSize, total) {
    /* sdd-asis-lifecycle:begin pageNav — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (total < 1) {
        return "";
    }
    let ret = "";
    const PAGEBLOCK = 10;
    const totalPages = Math.floor((total - 1) / pageSize) + 1;
    let firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) {
        firstPage = 1;
    }
    let lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) {
        lastPage = totalPages;
    }
    if (firstPage > PAGEBLOCK) {
        ret += scwin.navAnchor(funcName, 1, "<<처음") + "&nbsp;\n";
        ret += scwin.navAnchor(funcName, (firstPage - 1), "<이전") + "&nbsp;\n";
    }
    for (i = firstPage; i <= lastPage; i++) {
        if (pageNum === i) {
            ret += "<a class='active' onclick='return false;' href='#page_link_" + 1 + "'>" + i + "</a>&nbsp;\n";
        } else {
            ret += scwin.navAnchor(funcName, i, i) + "&nbsp;\n";
        }
    }
    if (lastPage < totalPages) {
        ret += scwin.navAnchor(funcName, (lastPage + 1), "다음>") + "&nbsp;\n";
        ret += "&nbsp;" + scwin.navAnchor(funcName, totalPages, "끝>>") + "\n";
    }
    return ret;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.navAnchor
 * @author Inswave
 * @date 2026. 09. 29
 * @param funcName pageNo anchorText
 * @returns
 * @hidden N
*/
scwin.navAnchor = function (funcName, pageNo, anchorText) {
    /* sdd-asis-lifecycle:begin navAnchor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return "<a onclick='" + funcName + "(" + pageNo + ");return false;' href='#page_link_" + anchorText + "'>" + anchorText + "</a>";
    /* sdd-asis-lifecycle:end */
};
